function initReveal(){const e=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&(t.target.classList.add("visible"),e.unobserve(t.target))})},{threshold:.08,rootMargin:"-30px"});document.querySelectorAll(".sr:not(.visible)").forEach(t=>e.observe(t))}function initNavScroll(){const e=document.getElementById("navbar"),t=document.getElementById("nav-logo");e&&!e.classList.contains("nav--solid")&&window.addEventListener("scroll",()=>{window.scrollY>60?(e.classList.add("scrolled"),t&&(t.src="/web-assets/Logo_Color.svg")):(e.classList.remove("scrolled"),t&&(t.src="/web-assets/Logo_Blanco.svg"))},{passive:!0})}function initMobile(){const e=document.getElementById("mobile-toggle"),t=document.getElementById("mobile-menu"),n=document.getElementById("mobile-close");e&&t&&(e.addEventListener("click",()=>t.classList.add("open")),n&&n.addEventListener("click",()=>t.classList.remove("open")),t.querySelectorAll("a").forEach(e=>e.addEventListener("click",()=>t.classList.remove("open"))))}function initFAQ(){document.querySelectorAll(".faq__q").forEach(e=>{e.addEventListener("click",()=>e.closest(".faq__item").classList.toggle("open"))})}document.addEventListener("DOMContentLoaded",()=>{initReveal(),initNavScroll(),initMobile(),initFAQ()});